using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [SerializeField] private bool debugLogs = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogs) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogs)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Serialization;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [FormerlySerializedAs("debugLogs")]
    [SerializeField] private bool debugLogsDirectional = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogsDirectional) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogsDirectional)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class GenericObject2 : MonoBehaviour, IInteractable, IHoldInteractable
{
    [Header("Configuración de objeto")]
    [SerializeField] private MaterialPrefabSO materialPrefabsSO; 
    [SerializeField] private BridgeQuadrantSO.EraType era = BridgeQuadrantSO.EraType.Prehistoric;
    [SerializeField] private InteractPriority interactPriority = InteractPriority.Medium;

    [Header("Configuración de mezcladora")]
    [SerializeField] private float tiempoCoccion = 1.5f; 
    [SerializeField] private Transform slotVisualTipo1;
    [SerializeField] private Transform slotVisualTipo2; 

    private bool slotTipo1Ocupado = false;
    private bool slotTipo2Ocupado = false;
    private bool enProcesoCoccion = false;

    [Header("Interacción manual (Medieval)")]
    [SerializeField] private float tiempoMantenerE = 1.5f; // segundos que hay que mantener presionado
    private bool esperandoHold = false;
    private float tiempoHoldActual = 0f;
    private GameObject jugadorInteractuando = null;


    public InteractPriority InteractPriority => interactPriority;

    // Método para obtener la era del objeto
    public BridgeQuadrantSO.EraType GetEra()
    {
        return era;
    }

    private void Start()
    {

        if (materialPrefabsSO == null)
        {
            Debug.LogError("No se ha asignado el MaterialPrefabSO en " + gameObject.name);
        }


        ActualizarVisualesSlots();
    }

    private void Update()
    {
        // Progreso de interacción mantenida solo aplica a la era medieval
        if (era == BridgeQuadrantSO.EraType.Medieval && esperandoHold && jugadorInteractuando != null)
        {
            // Solo avanzar si ambos materiales siguen cargados y no hay cocción en curso
            if (slotTipo1Ocupado && slotTipo2Ocupado && !enProcesoCoccion && CanStartProcess())
            {
                tiempoHoldActual += Time.deltaTime;
                if (tiempoHoldActual >= tiempoMantenerE)
                {
                    // Iniciar el proceso de creación y resetear el hold
                    if (CanStartProcess())
                    {
                        StartCoroutine(ProcesarMaterial());
                    }
                    ResetearHold();
                }
            }
            else
            {
                // Si ya no están disponibles las condiciones, cancelar el hold
                ResetearHold();
            }
        }
    }


    public void Interact(GameObject interactor)
    {
        if (enProcesoCoccion)
        {
            Debug.Log("Mezcladora en proceso de cocción, espera a que termine.");
            return;
        }

        PlayerObjectHolder playerObjectHolder = interactor.GetComponent<PlayerObjectHolder>();

        if (playerObjectHolder == null || !playerObjectHolder.HasObjectInHand())
        {
            if (slotTipo1Ocupado && slotTipo2Ocupado)
            {
                if (era == BridgeQuadrantSO.EraType.Prehistoric && !enProcesoCoccion)
                {
                    if (CanStartProcess())
                    {
                        StartCoroutine(ProcesarMaterial());
                    }
                }
                else if (era == BridgeQuadrantSO.EraType.Medieval)
                {
                    // Iniciar interacción mantenida
                    if (!esperandoHold)
                    {
                        esperandoHold = true;
                        tiempoHoldActual = 0f;
                        jugadorInteractuando = interactor;
                        Debug.Log("Mantén presionado el botón para activar la cocción (era medieval).");
                    }
                }
            }
            else
            {
                Debug.Log("No tienes un material para colocar en la mezcladora o ésta no está lista para entregar.");
            }
            return;
        }

        GameObject heldObject = playerObjectHolder.GetHeldObject();
        int materialTipo = DeterminarTipoMaterial(heldObject);

        switch (materialTipo)
        {
            case 1:
                if (!slotTipo1Ocupado)
                {
                    slotTipo1Ocupado = true;
                    playerObjectHolder.UseHeldObject(); 
                    ActualizarVisualesSlots();
                    VerificarCoccionAutomatica();
                    Debug.Log("Material tipo 1 colocado en la mezcladora.");
                }
                else
                {
                    Debug.Log("Ya hay un material tipo 1 en la mezcladora.");
                }
                break;

            case 2:
                if (!slotTipo2Ocupado)
                {
                    slotTipo2Ocupado = true;
                    playerObjectHolder.UseHeldObject(); 
                    ActualizarVisualesSlots();
                    VerificarCoccionAutomatica();
                    Debug.Log("Material tipo 2 colocado en la mezcladora.");
                }
                else
                {
                    Debug.Log("Ya hay un material tipo 2 en la mezcladora.");
                }
                break;

            default:
                Debug.Log("Este material no se puede usar en la mezcladora.");
                break;
        }
    }

    // Cancelación al soltar la tecla de interacción
    public void DetenerInteraccion()
    {
        if (esperandoHold)
        {
            ResetearHold();
            Debug.Log("Interacción cancelada. Debes mantener presionado para iniciar la cocción.");
        }
    }


    private int DeterminarTipoMaterial(GameObject objeto)
    {
        if (objeto == null) return 0;


        if (objeto.GetComponent<MaterialTipo1>() != null)
            return 1;


        BridgeMaterialInfo materialInfo = objeto.GetComponent<BridgeMaterialInfo>();
        if (materialInfo != null)
        {

            if (materialInfo.layerIndex == 0) return 1;
            if (materialInfo.layerIndex == 1) return 2;
        }

        return 0; 
    }


    private void ActualizarVisualesSlots()
    {
        if (slotVisualTipo1 != null)
            slotVisualTipo1.gameObject.SetActive(slotTipo1Ocupado);

        if (slotVisualTipo2 != null)
            slotVisualTipo2.gameObject.SetActive(slotTipo2Ocupado);
    }


    private void VerificarCoccionAutomatica()
    {
        if (era == BridgeQuadrantSO.EraType.Prehistoric && slotTipo1Ocupado && slotTipo2Ocupado && !enProcesoCoccion && CanStartProcess())
        {
            StartCoroutine(ProcesarMaterial());
        }
    }

    private IEnumerator ProcesarMaterial()
    {
        enProcesoCoccion = true;

        Debug.Log("Comenzando proceso de cocción...");

        yield return new WaitForSeconds(tiempoCoccion);

        GameObject materialTipo3Prefab = materialPrefabsSO.GetMaterialPrefab(3, era);
        if (materialTipo3Prefab != null)
        {
            Vector3 spawnPosition = transform.position + transform.forward * 1.0f;
            Instantiate(materialTipo3Prefab, spawnPosition, Quaternion.identity);
            Debug.Log("Material tipo 3 creado con éxito.");
        }
        else
        {
            Debug.LogError($"No se encontró prefab para material tipo 3 de la era {era}");
        }

        slotTipo1Ocupado = false;
        slotTipo2Ocupado = false;
        enProcesoCoccion = false;
        ActualizarVisualesSlots();
    }

    public void IniciarCoccionManual()
    {
        if (era == BridgeQuadrantSO.EraType.Medieval && slotTipo1Ocupado && slotTipo2Ocupado && !enProcesoCoccion && CanStartProcess())
        {
            StartCoroutine(ProcesarMaterial());
        }
    }

    // Punto de extensión para clases derivadas (e.g., hornos con gating por calor)
    protected virtual bool CanStartProcess()
    {
        return true;
    }

    private void ResetearHold()
    {
        esperandoHold = false;
        tiempoHoldActual = 0f;
        jugadorInteractuando = null;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class GenericObject2 : MonoBehaviour, IInteractable, IHoldInteractable
{
    [Header("Configuración de objeto")]
    [SerializeField] private MaterialPrefabSO materialPrefabsSO; 
    [SerializeField] private BridgeQuadrantSO.EraType era = BridgeQuadrantSO.EraType.Prehistoric;
    [SerializeField] private InteractPriority interactPriority = InteractPriority.Medium;

    [Header("Configuración de mezcladora")]
    [SerializeField] private float tiempoCoccion = 1.5f; 
    [SerializeField] private Transform slotVisualTipo1;
    [SerializeField] private Transform slotVisualTipo2; 

    private bool slotTipo1Ocupado = false;
    private bool slotTipo2Ocupado = false;
    private bool enProcesoCoccion = false;

    [Header("Interacción manual (Medieval)")]
    [SerializeField] private float tiempoMantenerE = 1.5f; // segundos que hay que mantener presionado
    private bool esperandoHold = false;
    private float tiempoHoldActual = 0f;
    private GameObject jugadorInteractuando = null;


    public InteractPriority InteractPriority => interactPriority;

    // Método para obtener la era del objeto
    public BridgeQuadrantSO.EraType GetEra()
    {
        return era;
    }

    private void Start()
    {

        if (materialPrefabsSO == null)
        {
            Debug.LogError("No se ha asignado el MaterialPrefabSO en " + gameObject.name);
        }


        ActualizarVisualesSlots();
    }

    private void Update()
    {
        // Progreso de interacción mantenida solo aplica a la era medieval
        if (era == BridgeQuadrantSO.EraType.Medieval && esperandoHold && jugadorInteractuando != null)
        {
            // Solo avanzar si ambos materiales siguen cargados y no hay cocción en curso
            if (slotTipo1Ocupado && slotTipo2Ocupado && !enProcesoCoccion && CanStartProcess())
            {
                tiempoHoldActual += Time.deltaTime;
                if (tiempoHoldActual >= tiempoMantenerE)
                {
                    // Iniciar el proceso de creación y resetear el hold
                    if (CanStartProcess())
                    {
                        StartCoroutine(ProcesarMaterial());
                    }
                    ResetearHold();
                }
            }
            else
            {
                // Si ya no están disponibles las condiciones, cancelar el hold
                ResetearHold();
            }
        }

        // Auto-arranque para eras que lo permitan (p.ej. Prehistoric por defecto, Industrial vía override)
        if (ShouldAutoStart() && slotTipo1Ocupado && slotTipo2Ocupado && !enProcesoCoccion && CanStartProcess())
        {
            StartCoroutine(ProcesarMaterial());
        }
    }


    public void Interact(GameObject interactor)
    {
        if (enProcesoCoccion)
        {
            Debug.Log("Mezcladora en proceso de cocción, espera a que termine.");
            return;
        }

        PlayerObjectHolder playerObjectHolder = interactor.GetComponent<PlayerObjectHolder>();

        if (playerObjectHolder == null || !playerObjectHolder.HasObjectInHand())
        {
            if (slotTipo1Ocupado && slotTipo2Ocupado)
            {
                if (era == BridgeQuadrantSO.EraType.Prehistoric && !enProcesoCoccion)
                {
                    if (CanStartProcess())
                    {
                        StartCoroutine(ProcesarMaterial());
                    }
                }
                else if (era == BridgeQuadrantSO.EraType.Medieval)
                {
                    // Iniciar interacción mantenida
                    if (!esperandoHold)
                    {
                        esperandoHold = true;
                        tiempoHoldActual = 0f;
                        jugadorInteractuando = interactor;
                        Debug.Log("Mantén presionado el botón para activar la cocción (era medieval).");
                    }
                }
            }
            else
            {
                Debug.Log("No tienes un material para colocar en la mezcladora o ésta no está lista para entregar.");
            }
            return;
        }

        GameObject heldObject = playerObjectHolder.GetHeldObject();
        int materialTipo = DeterminarTipoMaterial(heldObject);

        switch (materialTipo)
        {
            case 1:
                if (!slotTipo1Ocupado)
                {
                    slotTipo1Ocupado = true;
                    playerObjectHolder.UseHeldObject(); 
                    ActualizarVisualesSlots();
                    VerificarCoccionAutomatica();
                    Debug.Log("Material tipo 1 colocado en la mezcladora.");
                }
                else
                {
                    Debug.Log("Ya hay un material tipo 1 en la mezcladora.");
                }
                break;

            case 2:
                if (!slotTipo2Ocupado)
                {
                    slotTipo2Ocupado = true;
                    playerObjectHolder.UseHeldObject(); 
                    ActualizarVisualesSlots();
                    VerificarCoccionAutomatica();
                    Debug.Log("Material tipo 2 colocado en la mezcladora.");
                }
                else
                {
                    Debug.Log("Ya hay un material tipo 2 en la mezcladora.");
                }
                break;

            default:
                Debug.Log("Este material no se puede usar en la mezcladora.");
                break;
        }
    }

    // Cancelación al soltar la tecla de interacción
    public void DetenerInteraccion()
    {
        if (esperandoHold)
        {
            ResetearHold();
            Debug.Log("Interacción cancelada. Debes mantener presionado para iniciar la cocción.");
        }
    }


    private int DeterminarTipoMaterial(GameObject objeto)
    {
        if (objeto == null) return 0;


        if (objeto.GetComponent<MaterialTipo1>() != null)
            return 1;


        BridgeMaterialInfo materialInfo = objeto.GetComponent<BridgeMaterialInfo>();
        if (materialInfo != null)
        {

            if (materialInfo.layerIndex == 0) return 1;
            if (materialInfo.layerIndex == 1) return 2;
        }

        return 0; 
    }


    private void ActualizarVisualesSlots()
    {
        if (slotVisualTipo1 != null)
            slotVisualTipo1.gameObject.SetActive(slotTipo1Ocupado);

        if (slotVisualTipo2 != null)
            slotVisualTipo2.gameObject.SetActive(slotTipo2Ocupado);
    }


    private void VerificarCoccionAutomatica()
    {
        if (ShouldAutoStart() && slotTipo1Ocupado && slotTipo2Ocupado && !enProcesoCoccion && CanStartProcess())
        {
            StartCoroutine(ProcesarMaterial());
        }
    }

    private IEnumerator ProcesarMaterial()
    {
        enProcesoCoccion = true;

        Debug.Log("Comenzando proceso de cocción...");

        yield return new WaitForSeconds(tiempoCoccion);

        GameObject materialTipo3Prefab = materialPrefabsSO.GetMaterialPrefab(3, era);
        if (materialTipo3Prefab != null)
        {
            Vector3 spawnPosition = transform.position + transform.forward * 1.0f;
            Instantiate(materialTipo3Prefab, spawnPosition, Quaternion.identity);
            Debug.Log("Material tipo 3 creado con éxito.");
        }
        else
        {
            Debug.LogError($"No se encontró prefab para material tipo 3 de la era {era}");
        }

        slotTipo1Ocupado = false;
        slotTipo2Ocupado = false;
        enProcesoCoccion = false;
        ActualizarVisualesSlots();
    }

    public void IniciarCoccionManual()
    {
        if (era == BridgeQuadrantSO.EraType.Medieval && slotTipo1Ocupado && slotTipo2Ocupado && !enProcesoCoccion && CanStartProcess())
        {
            StartCoroutine(ProcesarMaterial());
        }
    }

    // Punto de extensión para clases derivadas (e.g., hornos con gating por calor)
    protected virtual bool CanStartProcess()
    {
        return true;
    }

    // Nuevo punto de extensión: por defecto sólo auto-arranca en Prehistórica; derivadas pueden habilitar otras eras
    protected virtual bool ShouldAutoStart()
    {
        return era == BridgeQuadrantSO.EraType.Prehistoric;
    }

    private void ResetearHold()
    {
        esperandoHold = false;
        tiempoHoldActual = 0f;
        jugadorInteractuando = null;
    }
}

// csharp
using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;

[DisallowMultipleComponent]
[RequireComponent(typeof(Collider))]
public class Tutorial2End : MonoBehaviour
{
    [Header("Condición")]
    [SerializeField] private string requiredItemTag = "BridgeMaterial1";

    [Header("Entrada del jugador")]
    [SerializeField] private KeyCode activationKeyPrimary = KeyCode.F;
    [SerializeField] private KeyCode activationKeySecondary = KeyCode.L;

    [Header("Siguiente nivel")]
    [SerializeField] private string nextSceneName;
    [SerializeField] private float loadDelaySeconds = 0.25f;

    private bool triggered;
    private int materialsInside;

    private void Reset()
    {
        var col = GetComponent<Collider>();
        if (col != null) col.isTrigger = true;
    }

    private void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag(requiredItemTag))
            materialsInside++;
    }

    private void OnTriggerExit(Collider other)
    {
        if (other.CompareTag(requiredItemTag))
            materialsInside = Mathf.Max(0, materialsInside - 1);
    }

    private void Update()
    {
        if (triggered);
        if (string.IsNullOrWhiteSpace(nextSceneName)) return;
        if (materialsInside <= 0) return;

        if (Input.GetKeyDown(activationKeyPrimary) || Input.GetKeyDown(activationKeySecondary))
        {
            triggered = true;
            StartCoroutine(LoadNextSceneAfterDelay());
        }
    }

    private IEnumerator LoadNextSceneAfterDelay()
    {
        if (loadDelaySeconds > 0f)
            yield return new WaitForSeconds(loadDelaySeconds);

        SceneManager.LoadScene(nextSceneName);
    }
}

